#include <vector>
#include <set>
#include <iterator>

int main() {
    std::vector<int> v = {1, 2, 3};
    std::set<int> s = {4, 5, 6};

    // 1. Random Access (Vector)
    v.begin()[2] = 99; // O(1) indexing allowed

    // 2. Bidirectional (Set)
    auto it_s = s.begin();
    // *it_s = 7; // ERROR: Set elements are constant (const value_type)

    // Check category trait (requires C++17 or older traits)
    using V_Cat = std::iterator_traits<decltype(v.begin())>::iterator_category;
    // V_Cat is std::random_access_iterator_tag
}
